path = []
def walk(index, total):
    if index == 3:
        if total == 1:
            print("match", "".join(path))
        return
    for sign, change in [("+", 1), ("-", -1)]:
        path.append(sign)
        walk(index + 1, total + change)
        path.pop()
walk(0, 0)
print("depth", len(path))

