cache = {}
blocked = {(1, 1)}
def count(r, c):
    if (r, c) in blocked:
        return 0
    if r == 2 and c == 2:
        return 1
    if r > 2 or c > 2:
        return 0
    if (r, c) not in cache:
        cache[(r, c)] = count(r + 1, c) + count(r, c + 1)
        print("memo", r, c, cache[(r, c)])
    return cache[(r, c)]
print("paths", count(0, 0))

tree = {"root": ["L", "R"], "L": ["LL", "LR"], "R": ["RL"], "LL": [], "LR": [], "RL": []}
weights = {"root": 1, "L": 2, "R": 3, "LL": 4, "LR": 1, "RL": 2}
path = []
def visit(node, score):
    path.append(node)
    score += weights[node]
    if not tree[node]:
        if score % 2 == 1:
            print("/".join(path), score)
    else:
        for child in tree[node]:
            visit(child, score)
